from textual.app import App, ComposeResult
from textual.widgets import Button, Static
from textual.message import Message


class ChildWidget(Static):
    """Child widget that sends custom messages."""

    class CustomMessage(Message):
        """Custom message sent by ChildWidget."""

        def __init__(self, content: str) -> None:
            super().__init__()
            self.content = content

    def compose(self) -> ComposeResult:
        yield Button("Click Me", id="btn")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Send custom message when button is pressed."""
        self.post_message(self.CustomMessage("Message from child widget!"))


class ParentWidget(Static):
    """Parent widget that receives messages."""

    def compose(self) -> ComposeResult:
        yield ChildWidget(id="child")
        yield Static("Waiting for message...", id="output")

    def on_child_custom_message(self, message: ChildWidget.CustomMessage) -> None:
        """Handle custom message from child widget."""
        output = self.query_one("#output", Static)
        output.update(f"Received: {message.content}")


class MyApp(App):
    """Main application."""

    CSS = """
    ParentWidget {
        height: 100%;
    }

    ChildWidget {
        border: solid blue;
        padding: 1;
    }

    #output {
        border: solid green;
        padding: 1;
        height: 1fr;
    }
    """

    def compose(self) -> ComposeResult:
        yield ParentWidget()


if __name__ == "__main__":
    app = MyApp()
    app.run()

